import json
def g(n,d): json.dump(d,open(n+'.json','w'),ensure_ascii=False,indent=1)
L=lambda en,pt,fr:[en,pt,fr]
def migas(t): return L(*[f'<a href="/">{a}</a><span aria-hidden="true">/</span><a href="/portafolio/">{b}</a><span aria-hidden="true">/</span><span aria-current="page">{c}</span>' for a,b,c in zip(("Home","Início","Accueil"),("Projects","Projetos","Projets"),t)])
def estado(t): return L(*[f'{x} <span class="siles-estado siles-estado--exito">{y}</span>' for x,y in zip(t,("Live","No ar","En ligne"))])
reto=L(*[f'<span class="siles-antetitulo">{x}</span>' for x in ("Challenge","Desafio","Défi")])
sol=L(*[f'<span class="siles-antetitulo">{x}</span>' for x in ("Solution","Solução","Solution")])
